insert into public.formula_chapters (id, subject_id, title, slug, sort_order)
values
  ('neet-biology-human-health-and-diseases', 'neet-biology', 'Human Health and Diseases', 'human-health-and-diseases', 28),
  ('neet-biology-enhancement-of-food-production', 'neet-biology', 'Enhancement of Food Production', 'enhancement-of-food-production', 29),
  ('neet-biology-microbes-in-human-welfare', 'neet-biology', 'Microbes in Human Welfare', 'microbes-in-human-welfare', 30)
