insert into public.formula_cards (
  id, chapter_id, title, card_type, body, formulas, variables, conditions, table_data, diagram_data, diagram_svg, recall_data, importance, source_page, sort_order, is_active
)
values
  ('neet-biology-human-health-and-diseases-health-disease-basics', 'neet-biology-human-health-and-diseases', 'Health and Disease Basics', 'concept', 'Health is complete physical, mental and social well-being; disease adversely affects organ or system functioning.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Health","Complete physical, mental and social well-being"],["Affected by","Genetic disorders, infections and lifestyle including food, water, rest, exercise and habits"],["Disease","Adverse effect on functioning of organs or systems"],["Infectious disease","Transmits from person to person"],["Non-infectious disease","Does not transmit; cancer is the source example"]]}'::jsonb, null, null, '{"recall_question":"Which disease type transmits person to person?","reveal_answer":"Infectious disease.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 117, 1, true),
  ('neet-biology-human-health-and-diseases-major-infectious-diseases', 'neet-biology-human-health-and-diseases', 'Major Infectious Diseases', 'comparison', 'The source lists bacterial, viral, protozoan, helminthic and fungal diseases with their agents and routes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Disease","Causative organism","Transmission/vector","Major source feature"],"rows":[["Typhoid","Salmonella typhi","Food and water; enters small intestine and migrates via blood","Widal test confirms"],["Pneumonia","Streptococcus pneumoniae and Haemophilus influenzae","Droplets/aerosols or sharing utensils","Alveoli become fluid-filled"],["Common cold","Rhinoviruses","Droplets or contaminated objects","Infects nose and respiratory passage, not lungs"],["Malaria","Plasmodium sp.","Female Anopheles mosquito","Haemozoin causes chill and high fever every 3-4 days"],["Amoebiasis","Entamoeba histolytica","Houseflies contaminate food and water","Stools with excess mucus and blood clots"],["Ascariasis","Ascaris","Food/water contaminated with eggs","May block intestinal passage"],["Filariasis","Wuchereria bancrofti and W. malayi","Female Culex mosquito","Chronic inflammation of lymphatic vessels"],["Ring worm","Microsporum, Trichophyton and Epidermophyton","Soil or shared towels, clothes, combs etc.","Dry scaly lesions with intense itching"]]}'::jsonb, null, null, '{"recall_question":"Which test confirms typhoid in the source?","reveal_answer":"Widal test.","key_points":[],"examples":[],"neet_traps":["Disease, pathogen and vector are separate recall hooks."]}'::jsonb, 5, 117, 2, true),
  ('neet-biology-human-health-and-diseases-typhoid', 'neet-biology-human-health-and-diseases', 'Typhoid Recall', 'fact', 'Typhoid is caused by Salmonella typhi and spreads through contaminated food and water.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Entry","Small intestine through food and water"],["Migration","Migrates to other organs through blood"],["Symptoms","Sustained high fever 39°-40°C, headache, weakness, stomach pain, constipation and loss of appetite"],["Severe outcome","Intestinal perforation and death may occur"],["Carrier example","Mary Mallon, Typhoid Mary, spread typhoid through food as a professional cook"]]}'::jsonb, null, null, '{"recall_question":"Which bacterium causes typhoid?","reveal_answer":"Salmonella typhi.","key_points":["Widal test confirms the disease."],"examples":[],"neet_traps":[]}'::jsonb, 5, 117, 3, true),
  ('neet-biology-human-health-and-diseases-pneumonia-common-cold', 'neet-biology-human-health-and-diseases', 'Pneumonia vs Common Cold', 'comparison', 'Both involve the respiratory system, but their sites and agents differ.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Pneumonia","Common cold"],"rows":[["Agent","Streptococcus pneumoniae and Haemophilus influenzae","Rhinoviruses"],["Site","Lung alveoli","Nose and respiratory passage, not lungs"],["Transmission","Droplets/aerosols or shared glasses and utensils","Droplets or contaminated objects such as pens, books, cups, doorknobs and computer accessories"],["Features","Respiratory problems, fever, chills, cough and headache; severe cases grey to bluish lips/fingernails","Nasal congestion/discharge, fever, headache, sore throat, cough, hoarseness and tiredness"],["Duration","Not specified here","3-7 days"]]}'::jsonb, null, null, '{"recall_question":"Which common respiratory infection does not infect lungs in the source?","reveal_answer":"Common cold.","key_points":[],"examples":[],"neet_traps":["Common cold infects nose and respiratory passage, not lungs."]}'::jsonb, 5, 117, 4, true),
  ('neet-biology-human-health-and-diseases-vector-disease-traps', 'neet-biology-human-health-and-diseases', 'Disease, Pathogen and Vector Traps', 'neet_trap', 'NEET-style recall often swaps pathogen, vector and carrier.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Disease","Pathogen","Vector/carrier"],"rows":[["Malaria","Plasmodium sp.; P. falciparum causes malignant malaria","Female Anopheles mosquito"],["Amoebiasis","Entamoeba histolytica","Houseflies are mechanical carriers"],["Filariasis","Wuchereria bancrofti and W. malayi","Female Culex mosquito"],["Ring worm","Microsporum, Trichophyton and Epidermophyton","Soil or infected towels, clothes and combs"]]}'::jsonb, null, null, '{"recall_question":"Which mosquito transmits filariasis?","reveal_answer":"Female Culex mosquito.","key_points":[],"examples":[],"neet_traps":["Female Anopheles transmits malaria; female Culex transmits filariasis."]}'::jsonb, 5, 117, 5, true),
  ('neet-biology-human-health-and-diseases-prevention-control', 'neet-biology-human-health-and-diseases', 'Prevention and Control', 'classification', 'Personal hygiene, public hygiene, vector control, vaccination and antibiotics are listed as control measures.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Control route","Source-backed actions"],"rows":[["Personal hygiene","Clean body; clean drinking water and food"],["Public hygiene","Proper disposal of wastes and excreta; periodic cleaning and disinfection of water reservoirs, pools, cesspools and tanks"],["Airborne disease control","Avoid contact with infected persons and their belongings"],["Vector control","Avoid stagnant water; clean coolers; use mosquito nets, larvivorous fish Gambusia, insecticides and wire mesh"],["Vaccines/immunisation","Controlled smallpox, polio, diphtheria, pneumonia and tetanus"],["Antibiotics","Treat infectious diseases"]]}'::jsonb, null, null, '{"recall_question":"Which larvivorous fish is listed for mosquito control?","reveal_answer":"Gambusia.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 118, 6, true),
  ('neet-biology-human-health-and-diseases-lymphoid-organs', 'neet-biology-human-health-and-diseases', 'Primary vs Secondary Lymphoid Organs', 'comparison', 'Primary lymphoid organs mature lymphocytes; secondary lymphoid organs provide sites for antigen interaction.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Source-backed role","Examples"],"rows":[["Primary lymphoid organs","Lymphocytes mature and differentiate into antigen-sensitive lymphocytes","Bone marrow and thymus"],["Secondary lymphoid organs","Mature lymphocytes migrate, interact with antigens and proliferate into effector cells","Spleen, lymph nodes, tonsils, Peyer''s patches, MALT and appendix"]]}'::jsonb, null, null, '{"recall_question":"Which primary lymphoid organ is bilobed near the heart?","reveal_answer":"Thymus.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 118, 7, true),
  ('neet-biology-human-health-and-diseases-immune-classification', 'neet-biology-human-health-and-diseases', 'Innate vs Acquired Immunity', 'diagram', 'Innate immunity is present at birth; acquired immunity is pathogen-specific and has memory.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Innate immunity","Acquired immunity"],"rows":[["Specificity","Non-specific","Pathogen-specific"],["Timing","Present at birth","Developed during lifetime"],["Memory","Not emphasized","Has memory"],["Response pattern","Barriers act immediately","Primary response is low intensity; secondary/anamnestic response is high intensity"]]}'::jsonb, '{"type":"bio-immune-classification"}'::jsonb, null, '{"recall_question":"Which immunity has memory?","reveal_answer":"Acquired immunity.","key_points":[],"examples":[],"neet_traps":["Innate immunity is non-specific and present at birth."]}'::jsonb, 5, 118, 8, true),
  ('neet-biology-human-health-and-diseases-innate-barriers', 'neet-biology-human-health-and-diseases', 'Four Innate Barriers', 'classification', 'The source groups innate immunity into physical, physiological, cellular and cytokine barriers.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Barrier","Source-backed examples"],"rows":[["Physical","Skin; mucus coating respiratory, gastrointestinal and urinogenital tracts"],["Physiological","Gastric HCl, saliva and tears prevent microbial growth"],["Cellular","Phagocytes such as PMNL/neutrophils, monocytes, natural killer lymphocytes and macrophages"],["Cytokine","Virus-infected cells secrete interferon to protect non-infected cells"]]}'::jsonb, null, null, '{"recall_question":"Which cytokine barrier is secreted by virus-infected cells?","reveal_answer":"Interferon.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 118, 9, true),
  ('neet-biology-human-health-and-diseases-humoral-cell-mediated', 'neet-biology-human-health-and-diseases', 'Humoral vs Cell-Mediated Immunity', 'comparison', 'Acquired immunity works through antibodies and T-cell mediated responses.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Humoral immunity","Cell-mediated immunity"],"rows":[["Mediator","Antibodies in blood plasma","T cells"],["Also called","Antibody-mediated immune response or AMI","CMI"],["Source-linked role","B lymphocytes produce antibodies; T cells help B cells produce antibodies","Helps body differentiate self and non-self; important in graft rejection"]]}'::jsonb, null, null, '{"recall_question":"Which immune response involves antibodies in blood plasma?","reveal_answer":"Humoral immunity.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 118, 10, true),
  ('neet-biology-human-health-and-diseases-antibody-structure', 'neet-biology-human-health-and-diseases', 'Antibody Structure', 'diagram', 'An antibody has four polypeptide chains arranged as H2L2.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed detail"],"rows":[["Light chains","Two small chains"],["Heavy chains","Two longer chains"],["Formula","H2L2"],["Types listed","IgG, IgA, IgM, IgE and IgD"]]}'::jsonb, '{"type":"bio-antibody-structure"}'::jsonb, null, '{"recall_question":"What is the antibody chain formula in the source?","reveal_answer":"H2L2.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 118, 11, true),
  ('neet-biology-human-health-and-diseases-active-passive-immunity', 'neet-biology-human-health-and-diseases', 'Active vs Passive Immunity', 'comparison', 'Active immunity requires antibody production in the host; passive immunity directly supplies ready-made antibodies.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Active immunity","Passive immunity"],"rows":[["Basic idea","Antibodies are produced in the host after exposure to antigens","Ready-made antibodies are directly given"],["Speed","Slow","Quick response"],["Natural example","Natural infection by microbes","IgG from mother through placenta; IgA in colostrum"],["Artificial example","Microbes injected deliberately during immunization","Anti-tetanus serum"]]}'::jsonb, null, null, '{"recall_question":"Which immunity is quick because ready-made antibodies are given?","reveal_answer":"Passive immunity.","key_points":[],"examples":[],"neet_traps":["IgA in colostrum is natural passive immunity in the source."]}'::jsonb, 5, 119, 12, true),
  ('neet-biology-human-health-and-diseases-immunisation-vaccines', 'neet-biology-human-health-and-diseases', 'Immunisation Recall', 'process', 'Vaccination introduces antigenic proteins or inactivated pathogens to generate antibodies and memory B/T cells.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Basis","Memory of acquired immunity"],["Vaccine material","Antigenic proteins of pathogen or inactivated pathogen"],["Later infection","Antibodies neutralize pathogenic agents"],["Memory cells","Memory B and T cells are generated"],["Examples","Polio vaccine, Hepatitis B vaccine and DPT vaccine"],["Recombinant example","Hepatitis B vaccine produced from Yeast"]]}'::jsonb, null, null, '{"recall_question":"Which vaccine example is produced from Yeast by DNA recombinant technology?","reveal_answer":"Hepatitis B vaccine.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 119, 13, true),
  ('neet-biology-human-health-and-diseases-allergy-autoimmunity', 'neet-biology-human-health-and-diseases', 'Allergy and Autoimmunity', 'comparison', 'Allergy is exaggerated response to environmental antigens; autoimmunity is attack on self cells.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Condition","Source-backed recall","Examples/details"],"rows":[["Allergy","Exaggerated immune response to environmental antigens","Allergens include mites in dust, pollens, animal dander and fur"],["Allergy molecules","IgE binds mast cells and releases histamine and serotonin","Symptoms include sneezing, watery eyes, running nose, difficulty breathing, wheezing and skin rashes"],["Treatment listed","Anti-histamine, adrenaline and steroids","Asthma is listed as a respiratory disease due to allergy"],["Autoimmunity","Body attacks self cells due to genetic or unknown reasons","Rheumatoid arthritis"]]}'::jsonb, null, null, '{"recall_question":"Which antibody is linked with allergy in the source?","reveal_answer":"IgE.","key_points":[],"examples":[],"neet_traps":["Autoimmunity is self-cell attack, not allergy."]}'::jsonb, 5, 119, 14, true),
  ('neet-biology-human-health-and-diseases-aids-overview-transmission', 'neet-biology-human-health-and-diseases', 'AIDS: Transmission and Non-Transmission', 'neet_trap', 'AIDS is caused by HIV, a retrovirus with RNA genome, and spreads through body fluids.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Full form","Acquired Immuno Deficiency Syndrome"],["Cause","HIV, Human Immunodeficiency Virus; retrovirus with RNA genome"],["Transmission","Sexual contact, contaminated blood/blood products, infected needles and infected mother to child through placenta"],["Does not spread by","Touch or physical contact"],["Time lag","Few months to 5-10 years"],["Diagnosis","ELISA test"]]}'::jsonb, null, null, '{"recall_question":"Which test diagnoses AIDS in the source?","reveal_answer":"ELISA test.","key_points":[],"examples":[],"neet_traps":["HIV does not spread by touch or physical contact."]}'::jsonb, 5, 119, 15, true),
  ('neet-biology-human-health-and-diseases-hiv-life-cycle', 'neet-biology-human-health-and-diseases', 'HIV Infection Sequence', 'diagram', 'HIV first uses macrophages as virus factories and then reduces helper T-cell count.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","HIV enters macrophages after entering the body"],["2","Reverse transcriptase uses RNA genome to make viral DNA"],["3","Viral DNA incorporates into host DNA"],["4","Infected cells produce virus particles"],["5","HIV enters helper T-cells and produces progeny viruses"],["6","Helper T-cell number decreases and immunity weakens"]]}'::jsonb, '{"type":"bio-hiv-sequence"}'::jsonb, null, '{"recall_question":"Which enzyme converts HIV RNA to viral DNA?","reveal_answer":"Reverse transcriptase.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 119, 16, true),
  ('neet-biology-human-health-and-diseases-cancer-basics', 'neet-biology-human-health-and-diseases', 'Cancer Basics', 'concept', 'Cancer cells multiply abnormally and lose contact inhibition.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Cancer","Abnormal uncontrolled multiplication of cells forming tumour"],["Normal cells","Show contact inhibition"],["Cancer cells","Do not show contact inhibition"],["Metastasis","Tumour cells travel through blood to form new tumours"]]}'::jsonb, null, null, '{"recall_question":"What property is lost in cancer cells?","reveal_answer":"Contact inhibition.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 120, 17, true),
  ('neet-biology-human-health-and-diseases-benign-malignant', 'neet-biology-human-health-and-diseases', 'Benign vs Malignant Tumour', 'diagram', 'Benign tumours stay confined; malignant tumours invade and metastasize.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Benign tumour","Malignant tumour"],"rows":[["Spread","Confined to original location","Invades and damages surrounding tissues"],["Damage","Causes little damage","Proliferating neoplastic cells starve normal cells"],["Metastasis","Not described as spreading","Cells travel through blood and form new tumours"]]}'::jsonb, '{"type":"bio-cancer-metastasis"}'::jsonb, null, '{"recall_question":"Which tumour type shows metastasis?","reveal_answer":"Malignant tumour.","key_points":[],"examples":[],"neet_traps":["Benign tumours remain confined to origin."]}'::jsonb, 5, 120, 18, true),
  ('neet-biology-human-health-and-diseases-carcinogens-diagnosis-treatment', 'neet-biology-human-health-and-diseases', 'Cancer: Causes, Diagnosis and Treatment', 'classification', 'The source groups carcinogens and lists major diagnostic and treatment approaches.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Category","Source-backed details"],"rows":[["Physical carcinogens","Ionizing radiations such as X-rays and gamma rays; non-ionizing UV rays"],["Chemical carcinogens","Tobacco smoke, vinyl chloride, caffeine, nicotine and mustard gas"],["Biological carcinogens","Oncogenic viruses; activated c-onc proto-oncogenes"],["Diagnosis","Biopsy/histopathology; blood and bone marrow tests for leukemia; radiography, CT, MRI; antibodies; molecular biology"],["Treatment","Radiotherapy, chemotherapy, immunotherapy with alpha-interferon and surgery"]]}'::jsonb, null, null, '{"recall_question":"Which biological response modifier is named for cancer immunotherapy?","reveal_answer":"Alpha-interferon.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 120, 19, true),
  ('neet-biology-human-health-and-diseases-drug-categories', 'neet-biology-human-health-and-diseases', 'Drug Categories and Sources', 'comparison', 'The source links abused substances to plant or microbial sources and physiological effects.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Category","Source/example","Major source-backed effect"],"rows":[["Opioids","Morphine and heroin from Papaver somniferum latex","Bind opioid receptors; heroin is a depressant and slows body functions"],["Cannabinoids","Cannabis sativa; marijuana, hashish, charas and ganja","Interact with cannabinoid receptors and affect cardiovascular system"],["Coca alkaloid","Cocaine from Erythroxylum coca","Interferes dopamine transport; stimulates CNS causing euphoria and increased energy"],["Hallucinogenic plants","Atropa belladona and Datura","Listed as hallucinogenic plants"],["Medicinal sedatives/stimulants","Barbiturates, amphetamines and benzodiazepines","Abuse impairs physical, physiological and psychological functions"]]}'::jsonb, null, null, '{"recall_question":"Which plant yields cocaine?","reveal_answer":"Erythroxylum coca.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 120, 20, true),
  ('neet-biology-human-health-and-diseases-smoking-tobacco', 'neet-biology-human-health-and-diseases', 'Smoking and Tobacco Effects', 'fact', 'Nicotine stimulates adrenal hormone release, while smoking lowers oxygen delivery.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Nicotine","Stimulates adrenal gland to release adrenaline and noradrenaline"],["Effect of nicotine","Raises blood pressure and heart rate"],["Diseases listed","Lung, urinary bladder and throat cancers; bronchitis, emphysema, coronary heart disease and gastric ulcer"],["Chewing tobacco","Associated with oral cancer"],["Carbon monoxide","Increases in blood and reduces oxyhaemoglobin concentration, causing oxygen deficiency"]]}'::jsonb, null, null, '{"recall_question":"Why does smoking cause oxygen deficiency in the source?","reveal_answer":"It increases CO in blood and reduces oxyhaemoglobin concentration.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 120, 21, true),
  ('neet-biology-human-health-and-diseases-addiction-dependence', 'neet-biology-human-health-and-diseases', 'Addiction vs Dependence', 'comparison', 'Addiction is psychological attachment; dependence appears as withdrawal when regular dose is stopped.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Addiction","Dependence"],"rows":[["Meaning","Psychological attachment to drugs/alcohol","Body shows unpleasant withdrawal syndrome if regular dose is abruptly discontinued"],["Dose pattern","Tolerance at receptor level leads to higher doses","Regular dose discontinuation causes symptoms"],["Symptoms/effects","Compulsive use despite problems","Anxiety, shakiness, nausea, sweating and social adjustment problems"]]}'::jsonb, null, null, '{"recall_question":"Which term describes withdrawal symptoms after stopping regular dose?","reveal_answer":"Dependence.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 121, 22, true),
  ('neet-biology-human-health-and-diseases-abuse-prevention-control', 'neet-biology-human-health-and-diseases', 'Drug and Alcohol Abuse Control', 'classification', 'The source emphasizes education, family/peer support and professional help.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Area","Source-backed recall"],"rows":[["Adolescence","Bridge between childhood and adulthood, 12-18 years"],["Causes of use","Curiosity, adventure, escape from problems, academic pressure, media, unstable family and peer pressure"],["Possible effects","Reckless behaviour, coma/death, nervous system damage, liver cirrhosis, family distress, AIDS/hepatitis B spread"],["Prevention/control","Avoid peer pressure; education and counselling; help from parents and peers; look for danger signs; professional and medical help"]]}'::jsonb, null, null, '{"recall_question":"What age range is adolescence in the source?","reveal_answer":"12-18 years.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 121, 23, true),
  ('neet-biology-human-health-and-diseases-malaria', 'neet-biology-human-health-and-diseases', 'Malaria Recall', 'fact', 'Malaria is caused by Plasmodium sp. and transmitted by female Anopheles mosquito.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Pathogens listed","Plasmodium vivax, P. malariae and P. falciparum"],["Most serious form","Malignant malaria caused by P. falciparum"],["Vector","Female Anopheles mosquito"],["Toxin","Haemozoin"],["Symptom rhythm","Chill and high fever every 3-4 days"]]}'::jsonb, null, null, '{"recall_question":"Which Plasmodium causes malignant malaria in the source?","reveal_answer":"P. falciparum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 117, 24, true),
  ('neet-biology-human-health-and-diseases-amoebiasis', 'neet-biology-human-health-and-diseases', 'Amoebiasis Recall', 'fact', 'Amoebiasis or amoebic dysentery is caused by Entamoeba histolytica.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Causative organism","Entamoeba histolytica"],["Carrier","Houseflies act as mechanical carriers"],["Transmission route","Houseflies transfer parasite from faeces to food and water"],["Symptoms","Constipation, abdominal pain and cramps; stools with excess mucus and blood clots"]]}'::jsonb, null, null, '{"recall_question":"Which organism causes amoebiasis?","reveal_answer":"Entamoeba histolytica.","key_points":[],"examples":[],"neet_traps":["Houseflies are mechanical carriers in amoebiasis."]}'::jsonb, 5, 117, 25, true),
  ('neet-biology-human-health-and-diseases-ascariasis', 'neet-biology-human-health-and-diseases', 'Ascariasis Recall', 'fact', 'Ascariasis is caused by Ascaris, an intestinal parasite.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Pathogen","Ascaris"],["Transmission","Soil, water, vegetables and fruits contaminated with faeces containing eggs"],["Symptoms","Internal bleeding, muscular pain, fever and anaemia"],["Severe effect","Blockage of intestinal passage"]]}'::jsonb, null, null, '{"recall_question":"Which helminth can block the intestinal passage in the source?","reveal_answer":"Ascaris.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 117, 26, true),
  ('neet-biology-human-health-and-diseases-filariasis', 'neet-biology-human-health-and-diseases', 'Filariasis Recall', 'fact', 'Filariasis or elephantiasis is caused by Wuchereria worms.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Pathogens","Wuchereria bancrofti and W. malayi"],["Vector","Female Culex mosquito"],["Site","Lymphatic vessels of lower limbs"],["Effect","Chronic inflammation over many years"],["Deformity","Lower limbs and genital organs may be deformed"]]}'::jsonb, null, null, '{"recall_question":"Which mosquito transmits filariasis?","reveal_answer":"Female Culex mosquito.","key_points":[],"examples":[],"neet_traps":["Female Anopheles is malaria; female Culex is filariasis."]}'::jsonb, 5, 117, 27, true),
  ('neet-biology-human-health-and-diseases-ringworm', 'neet-biology-human-health-and-diseases', 'Ring Worm Recall', 'fact', 'Ring worm is a fungal infection supported by heat and moisture.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Pathogens","Microsporum, Trichophyton and Epidermophyton"],["Common sites","Groin, between toes and other areas"],["Transmission","Soil or infected towels, clothes, combs etc."],["Symptoms","Dry scaly lesions on skin, nails and scalp with intense itching"],["Favouring conditions","Heat and moisture"]]}'::jsonb, null, null, '{"recall_question":"Name one fungus causing ring worm from the source.","reveal_answer":"Microsporum, Trichophyton or Epidermophyton.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 117, 28, true),
  ('neet-biology-enhancement-of-food-production-animal-husbandry-overview', 'neet-biology-enhancement-of-food-production', 'Animal Husbandry Overview', 'concept', 'Animal husbandry is the scientific practice of breeding and raising livestock.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Scope","Care and breeding of livestock such as buffaloes, cows, pigs, horses, cattle, sheep, camels and goats"],["Also includes","Poultry and fisheries"],["Problem noted","India and China have over 70% of world livestock but only 25% of world farm produce"],["Need","New technologies to increase productivity per unit"]]}'::jsonb, null, null, '{"recall_question":"What is animal husbandry?","reveal_answer":"Scientific agricultural practice of breeding and raising livestock.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 122, 1, true),
  ('neet-biology-enhancement-of-food-production-dairy-poultry-management', 'neet-biology-enhancement-of-food-production', 'Dairy and Poultry Management', 'comparison', 'Both focus on suitable breeds, disease control, feeding and hygiene.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Area","Dairy management","Poultry management"],"rows":[["Purpose","Increase yield and quality of milk/products","Food and eggs from domesticated birds"],["Breed focus","Good breeds with high yield and disease resistance","Disease-free suitable breeds"],["Management","Housing, adequate water, disease-free animals, quality/quantity fodder, hygiene in milking/storage/transport","Safe farm conditions, proper feed and water, hygiene and health care"],["Examples","Cattle and milk animals","Chicken, ducks, turkey and geese"]]}'::jsonb, null, null, '{"recall_question":"In dairy management, milk yield depends mainly on what?","reveal_answer":"Quality of breeds.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 122, 2, true),
  ('neet-biology-enhancement-of-food-production-inbreeding', 'neet-biology-enhancement-of-food-production', 'Inbreeding', 'concept', 'Inbreeding mates closely related individuals of the same breed for 4-6 generations.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Method","Identify and mate superior males and females of same breed; evaluate progeny"],["Superior female in cattle","Produces more milk per lactation"],["Superior bull","Gives superior progeny"],["Advantages","Increases homozygosity, evolves pure line, exposes harmful recessives, accumulates superior genes"],["Risk","Continued close inbreeding reduces fertility and productivity, called inbreeding depression"]]}'::jsonb, null, null, '{"recall_question":"What is the risk of continued close inbreeding?","reveal_answer":"Inbreeding depression.","key_points":["It reduces fertility and productivity."],"examples":[],"neet_traps":[]}'::jsonb, 5, 122, 3, true),
  ('neet-biology-enhancement-of-food-production-outbreeding-comparison', 'neet-biology-enhancement-of-food-production', 'Outcrossing, Cross-Breeding and Interspecific Hybridisation', 'comparison', 'Outbreeding includes mating unrelated animals by several routes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Method","Source-backed recall","Example/use"],"rows":[["Out-crossing","Same breed animals with no common ancestors on either side for 4-6 generations","Best for low milk productivity/growth rate; overcomes inbreeding depression"],["Cross-breeding","Superior males of one breed mated with superior females of another breed","Hisardale sheep in Punjab from Bikaneri ewes x Merino rams"],["Interspecific hybridisation","Male and female animals of different related species are mated","Mule from male ass x female horse"]]}'::jsonb, null, null, '{"recall_question":"Which breeding method produced Hisardale sheep?","reveal_answer":"Cross-breeding.","key_points":[],"examples":[],"neet_traps":["Out-crossing is within the same breed; cross-breeding uses two breeds."]}'::jsonb, 5, 122, 4, true),
  ('neet-biology-enhancement-of-food-production-ai-moet', 'neet-biology-enhancement-of-food-production', 'Artificial Insemination vs MOET', 'diagram', 'Both are controlled breeding techniques; MOET rapidly multiplies elite germplasm.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Technique","Source-backed recall"],"rows":[["Artificial insemination","Semen from male parent is injected into reproductive tract of selected female; semen may be used immediately or frozen and transported"],["MOET hormone step","Cow receives hormones such as FSH for follicular maturation and super ovulation"],["MOET ovulation","6-8 eggs per cycle instead of one"],["MOET transfer","Fertilised eggs at 8-32 cells are recovered non-surgically and transferred to surrogate mothers"],["Used in","Cattle, sheep, rabbits, buffaloes, mares etc."]]}'::jsonb, '{"type":"bio-moet-flow"}'::jsonb, null, '{"recall_question":"In MOET, fertilised eggs are recovered at which stage?","reveal_answer":"8-32 cells.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 122, 5, true),
  ('neet-biology-enhancement-of-food-production-apiculture-fisheries', 'neet-biology-enhancement-of-food-production', 'Apiculture and Fisheries', 'comparison', 'Apiculture manages honeybee hives; fisheries handle fish and aquatic animals.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Area","Source-backed recall","Examples/uses"],"rows":[["Apiculture","Maintenance of hives of honeybees for honey and beeswax","Common reared species Apis indica; beeswax used in cosmetics and polishes"],["Bee crop value","Beehives during flowering increase pollination, crop yield and honey yield","Sunflower, Brassica, apple and pear"],["Fisheries","Industry of catching, processing and selling fish, shellfish or aquatic animals","Prawn, crab, lobster and edible oyster"],["Freshwater fishes","Catla, Rohu and common carp","Aquaculture is farming aquatic organisms; pisciculture is farming fishes"],["Marine fishes","Hilsa, Sardines, Mackerel and Pomfrets","Blue Revolution is development/flourishing fishery industry"]]}'::jsonb, null, null, '{"recall_question":"Which honeybee species is listed as commonly reared?","reveal_answer":"Apis indica.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 123, 6, true),
  ('neet-biology-enhancement-of-food-production-plant-breeding-steps', 'neet-biology-enhancement-of-food-production', 'Plant Breeding Steps', 'diagram', 'Plant breeding manipulates plant species to create desired plant types.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed recall"],"rows":[["1. Collection of variability","Collect and preserve wild varieties, species and relatives; germplasm collection contains all alleles for all genes in a crop"],["2. Evaluation and selection of parents","Evaluate germplasm for desirable characters; multiply selected plants"],["3. Cross hybridisation","Combine desired characters from two parents"],["4. Selection/testing of superior recombinants","Select plants superior to parents and self-pollinate for uniformity/homozygosity"],["5. Testing/release/commercialisation","Test in research and farmers'' fields for at least 3 growing seasons across locations"]]}'::jsonb, '{"type":"bio-plant-breeding-sequence"}'::jsonb, null, '{"recall_question":"What is germplasm collection?","reveal_answer":"Entire collection of plants or seeds with all alleles for all genes in a crop.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 123, 7, true),
  ('neet-biology-enhancement-of-food-production-green-revolution-varieties', 'neet-biology-enhancement-of-food-production', 'Green Revolution Varieties', 'examples', 'The source links semi-dwarf wheat and rice varieties with India''s food production increase.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Crop","Source-backed varieties/details"],"rows":[["Wheat","Norman E. Borlaug developed semi-dwarf wheat; Sonalika and Kalyan Sona introduced in India in 1963"],["Rice","Semi-dwarf varieties from IR-8 at IRRI Philippines and Taichung Native-1 from Taiwan; later Jaya and Ratna in India"],["Production change","Wheat rose from 11 million tons to 75 million tons; rice from 35 million tons to 89.5 million tons during 1960-2000"],["Sugar cane","Saccharum barberi crossed with S. officinarum to combine north adaptation with thick stems and high sugar"],["Millets","Hybrid maize, jowar and bajra are high yielding and resistant to water stress"]]}'::jsonb, null, null, '{"recall_question":"Which two wheat varieties were introduced in India in 1963?","reveal_answer":"Sonalika and Kalyan Sona.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 123, 8, true),
  ('neet-biology-enhancement-of-food-production-disease-resistance-varieties', 'neet-biology-enhancement-of-food-production', 'Disease-Resistant Crop Varieties', 'examples', 'Resistant cultivars reduce dependence on fungicides and bactericides.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Crop","Variety","Resistant to"],"rows":[["Wheat","Himgiri","Leaf and stripe rust, hill bunt"],["Brassica","Pusa swarnim / Karan rai","White rust"],["Cauliflower","Pusa Shubhra; Pusa Snowball K-1","Black rot and curl blight black rot"],["Cowpea","Pusa Komal","Bacterial blight"],["Chilli","Pusa Sadabahar","Chilly mosaic virus, tobacco mosaic virus and leaf curl"]]}'::jsonb, null, null, '{"recall_question":"Which wheat variety resists leaf and stripe rust and hill bunt?","reveal_answer":"Himgiri.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 124, 9, true),
  ('neet-biology-enhancement-of-food-production-mutation-insect-resistance', 'neet-biology-enhancement-of-food-production', 'Mutation and Insect Resistance', 'classification', 'Mutation breeding and resistance traits provide new crop protection routes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Mutation breeding","Uses chemicals or radiations such as gamma rays to produce desirable mutations"],["Mung bean","Resistance to yellow mosaic virus and powdery mildew induced by mutations"],["Bhindi","Parbhani kranti developed by transferring yellow mosaic virus resistance from a wild species"],["Hairy leaves","Resistance to jassids in cotton and cereal leaf beetle in wheat"],["Solid stems","Wheat non-preference by stem sawfly"],["Biochemical trait","High aspartic acid and low nitrogen/sugar in maize resist maize stem borers"]]}'::jsonb, null, null, '{"recall_question":"Which bhindi variety resists yellow mosaic virus?","reveal_answer":"Parbhani kranti.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 124, 10, true),
  ('neet-biology-enhancement-of-food-production-insect-resistant-varieties', 'neet-biology-enhancement-of-food-production', 'Insect-Resistant Varieties', 'examples', 'The source lists crop varieties produced by hybridisation and selection for insect resistance.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Crop","Variety","Insect pests"],"rows":[["Brassica rapeseed mustard","Pusa Gaurav","Aphids"],["Flat bean","Pusa Sem 2 and Pusa Sem 3","Jassids, aphids and fruit borer"],["Okra/Bhindi","Pusa Sawani and Pusa A-4","Shoot and fruit borer"]]}'::jsonb, null, null, '{"recall_question":"Which Brassica variety resists aphids?","reveal_answer":"Pusa Gaurav.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 124, 11, true),
  ('neet-biology-enhancement-of-food-production-biofortification', 'neet-biology-enhancement-of-food-production', 'Biofortification', 'concept', 'Biofortification is breeding crops with higher nutrient levels to improve public health.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Objective","Source-backed focus"],"rows":[["Protein","Improve protein content and quality"],["Oil","Improve oil content and quality"],["Vitamins","Improve vitamin content"],["Micronutrients/minerals","Improve micronutrient and mineral content"],["Need","Hidden hunger from micronutrient, protein and vitamin deficiencies"]]}'::jsonb, null, null, '{"recall_question":"What is biofortification?","reveal_answer":"Breeding crops with higher levels of nutrients.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 124, 12, true),
  ('neet-biology-enhancement-of-food-production-biofortification-examples', 'neet-biology-enhancement-of-food-production', 'Biofortification Examples', 'examples', 'Use only source-listed nutrient-rich crop examples.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Improvement","Source-backed examples"],"rows":[["Amino acids","Maize hybrids with twice lysine and tryptophan compared to existing maize hybrids"],["Protein","Wheat variety Atlas 66 with high protein content"],["Iron","Iron-fortified rice variety containing over five times as much iron as common varieties"],["Vitamin A","Carrots, spinach and pumpkin"],["Vitamin C","Bitter gourd, bathua, mustard and tomato"],["Iron and calcium","Spinach and bathua"],["Protein","Beans: broad, lablab, French and garden peas"]]}'::jsonb, null, null, '{"recall_question":"Which wheat variety has high protein content?","reveal_answer":"Atlas 66.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 124, 13, true),
  ('neet-biology-enhancement-of-food-production-single-cell-protein', 'neet-biology-enhancement-of-food-production', 'Single Cell Protein', 'fact', 'SCP is protein derived from single-celled organisms and is an alternate protein source.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Examples","Spirulina and Methylophilus methylotrophus"],["Spirulina nutrients","Rich in protein, minerals, fats, carbohydrate and vitamins"],["Spirulina growth materials","Waste water from potato processing plants, straw, molasses, animal manure and sewage"],["Comparison value","A 250 Kg cow produces only 200 g protein/day; 250 g Methylophilus methylotrophus produces 25 tonnes protein"],["Reason","High rate of biomass production and growth"]]}'::jsonb, null, null, '{"recall_question":"Which bacterium is listed as an SCP example?","reveal_answer":"Methylophilus methylotrophus.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 125, 14, true),
  ('neet-biology-enhancement-of-food-production-tissue-culture-micropropagation', 'neet-biology-enhancement-of-food-production', 'Tissue Culture and Micropropagation', 'process', 'Tissue culture grows plant cells, tissues or organs in sterile medium under controlled aseptic conditions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall"],"rows":[["Totipotency","Ability to generate a whole plant from any cell or explant"],["Explant","Any part of a plant grown in a test tube under sterile nutrient media"],["Medium","Carbon source such as sucrose, inorganic salts, vitamins, amino acids and growth regulators such as auxins and cytokinins"],["Micropropagation","Producing thousands of plants in a very short time through tissue culture"],["Somaclones","Plants genetically identical to original plant"],["Examples","Tomato, banana and apple"]]}'::jsonb, null, null, '{"recall_question":"What is totipotency?","reveal_answer":"Ability to generate a whole plant from any cell or explant.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 125, 15, true),
  ('neet-biology-enhancement-of-food-production-virus-free-somatic-hybridisation', 'neet-biology-enhancement-of-food-production', 'Virus-Free Plants and Somatic Hybridisation', 'comparison', 'Tissue culture can recover healthy plants and create somatic hybrids.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Use","Source-backed method","Examples/details"],"rows":[["Virus-free plants","Remove meristem from infected plant and grow in vitro","Banana, sugarcane, potato etc."],["Somatic hybridisation","Fuse protoplasts from two varieties after digesting cell walls","Hybrid protoplast can grow into somatic hybrid"],["Pomato","Protoplast of tomato + protoplast of potato -> pomato","Hybrid has characteristics of tomato and potato but not all desired traits for commercial utilization"]]}'::jsonb, null, null, '{"recall_question":"Which plant part is used to recover virus-free plants?","reveal_answer":"Meristem.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 125, 16, true),
  ('neet-biology-microbes-in-human-welfare-household-products', 'neet-biology-microbes-in-human-welfare', 'Microbes in Household Products', 'examples', 'Household microbial products depend mainly on fermentation.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Product/process","Microbe","Source-backed recall"],"rows":[["Curd","Lactobacillus or LAB","Converts milk to curd by acids that coagulate and partially digest milk proteins; increases vitamin B12"],["Dosa/idli dough","Bacteria","Anaerobic fermentation produces CO2 and puffs up dough"],["Bread","Baker''s Yeast, Saccharomyces cerevisiae","Ferments dough"],["Toddy","Microbes in palm sap","Made by fermenting sap from palms"],["Swiss cheese","Propionibacterium sharmanii","Large holes due to CO2"],["Roquefort cheese","Penicillium roqueforti","Ripened by growing fungus on cheese"]]}'::jsonb, null, null, '{"recall_question":"Which bacterium produces holes in Swiss cheese?","reveal_answer":"Propionibacterium sharmanii.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 126, 1, true),
  ('neet-biology-microbes-in-human-welfare-industrial-products', 'neet-biology-microbes-in-human-welfare', 'Industrial Microbial Products', 'classification', 'Industrial products require growing microbes in large vessels called fermentors.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Product group","Source-backed examples"],"rows":[["Fermented beverages","Saccharomyces cerevisiae ferments malted cereals and fruit juices to ethanol"],["Without distillation","Wine and beer"],["With distillation","Whisky, Brandy, Rum, Gin and Arrack"],["Antibiotics","Chemical substances produced by microbes that kill or retard pathogen growth"],["Antibiotic uses","Treat plague, whooping cough, diphtheria, leprosy etc."]]}'::jsonb, null, null, '{"recall_question":"Which yeast is used in fermented beverages?","reveal_answer":"Saccharomyces cerevisiae.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 126, 2, true),
  ('neet-biology-microbes-in-human-welfare-penicillin', 'neet-biology-microbes-in-human-welfare', 'Penicillin Recall', 'fact', 'Penicillin was the first antibiotic discovered by Alexander Fleming.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Observation","Staphylococci could not grow around Penicillium notatum on unwashed culture plates"],["Discovery","Alexander Fleming extracted penicillin from the mould"],["Full potential","Earnest Chain and Howard Florey established its full potential as an effective antibiotic"],["Nobel Prize","Fleming, Chain and Florey were awarded Nobel Prize in 1945"]]}'::jsonb, null, null, '{"recall_question":"Which mould produced penicillin in Fleming''s observation?","reveal_answer":"Penicillium notatum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 126, 3, true),
  ('neet-biology-microbes-in-human-welfare-organic-acids', 'neet-biology-microbes-in-human-welfare', 'Organic Acid Producers', 'examples', 'The source lists exact microbe-acid pairs.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Microorganism","Product"],"rows":[["Aspergillus niger","Citric acid"],["Acetobacter aceti","Acetic acid"],["Clostridium butylicum","Butyric acid"],["Lactobacillus","Lactic acid"]]}'::jsonb, null, null, '{"recall_question":"Which fungus produces citric acid?","reveal_answer":"Aspergillus niger.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 126, 4, true),
  ('neet-biology-microbes-in-human-welfare-enzymes-bioactive', 'neet-biology-microbes-in-human-welfare', 'Enzymes and Bioactive Molecules', 'examples', 'Microbes produce enzymes and bioactive molecules used in medicine and industry.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Product","Microbe/source","Use"],"rows":[["Lipases","Microbes","Detergent formulations; remove oily stains from laundry"],["Pectinases and Proteases","Microbes","Clarify bottled juices"],["Streptokinase","Streptococcus","Clot buster for blood clots in myocardial infarction patients"],["Cyclosporine A","Trichoderma polysporum","Immunosuppressive agent in organ transplant patients"],["Statins","Monascus purpureus","Blood-cholesterol lowering agents; inhibit enzymes for cholesterol synthesis"]]}'::jsonb, null, null, '{"recall_question":"Which microbe produces Streptokinase?","reveal_answer":"Streptococcus.","key_points":[],"examples":[],"neet_traps":["Trichoderma polysporum produces Cyclosporine A, not Streptokinase."]}'::jsonb, 5, 126, 5, true),
  ('neet-biology-microbes-in-human-welfare-sewage-treatment-flow', 'neet-biology-microbes-in-human-welfare', 'Sewage Treatment Flow', 'diagram', 'Sewage treatment makes municipal waste-water less polluting before release.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Stage","Source-backed event"],"rows":[["Sewage","Municipal waste-water contains large organic matter and microbes"],["Primary treatment","Sequential filtration removes floating debris; sedimentation removes grit"],["Primary sludge/effluent","Settled solids form primary sludge; supernatant forms primary effluent"],["Secondary treatment","Primary effluent enters aeration tanks; useful aerobic microbes grow into flocs"],["BOD reduction","Microbes consume organic matter and reduce BOD"],["Activated sludge","Flocs sediment in settling tank; small part pumped back as inoculum"],["Anaerobic digesters","Remaining sludge produces gases such as CH4, H2S and CO2"]]}'::jsonb, '{"type":"bio-sewage-treatment"}'::jsonb, null, '{"recall_question":"What is activated sludge?","reveal_answer":"Sediment of bacterial flocs from the settling tank.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 126, 6, true),
  ('neet-biology-microbes-in-human-welfare-primary-secondary-sewage', 'neet-biology-microbes-in-human-welfare', 'Primary vs Secondary Sewage Treatment', 'comparison', 'Primary treatment is physical; secondary treatment is biological.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Primary treatment","Secondary treatment"],"rows":[["Nature","Physical removal of particles","Biological treatment"],["Processes","Sequential filtration and sedimentation","Aeration, growth of flocs, organic matter consumption and settling"],["Output terms","Primary sludge and primary effluent","Activated sludge and treated effluent"],["Key effect","Removes floating debris, soil and pebbles","Reduces BOD"]]}'::jsonb, null, null, '{"recall_question":"Which sewage treatment stage reduces BOD?","reveal_answer":"Secondary treatment.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 126, 7, true),
  ('neet-biology-microbes-in-human-welfare-bod-trap', 'neet-biology-microbes-in-human-welfare', 'BOD Recall Trap', 'neet_trap', 'BOD measures organic matter and polluting potential through oxygen consumption.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Full form","Biochemical Oxygen Demand"],["Definition","Amount of O2 consumed by bacteria to oxidize all organic matter in one litre of water"],["Indicates","Measure of organic matter present in water"],["Trap","Greater BOD means greater polluting potential"]]}'::jsonb, null, null, '{"recall_question":"What does greater BOD indicate?","reveal_answer":"Greater polluting potential.","key_points":[],"examples":[],"neet_traps":["BOD rises with organic matter/polluting potential."]}'::jsonb, 5, 126, 8, true),
  ('neet-biology-microbes-in-human-welfare-biogas-process', 'neet-biology-microbes-in-human-welfare', 'Biogas Production', 'diagram', 'Biogas is mainly CH4 produced by microbial activity under anaerobic conditions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Biogas","Mixture of gases, mainly CH4, used for cooking and lighting"],["Methanogens","Grow anaerobically on cellulosic material and produce CH4"],["Example","Methanobacterium"],["Natural locations","Anaerobic sludge and rumen of cattle"],["Dung","Rich in these bacteria; used to generate Gobar gas"],["Developed in India by","IARI and KVIC"]]}'::jsonb, '{"type":"bio-biogas-process"}'::jsonb, null, '{"recall_question":"Which methanogen example is given for biogas?","reveal_answer":"Methanobacterium.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 127, 9, true),
